export const SEMANTIC_PARTITIONS = [SEMANTIC, SEMANTIC_REGISTRY, SEMANTIC_REGISTRY_2, SEMANTIC_SESSION, SEMANTIC_EVENTS, SEMANTIC_RUNTIME, SEMANTIC_REMOTE]


